NAVY = "153454"


def parse(text):
    rows = [line.split("\t") for line in text.splitlines()]
    assert all(len(r) == len(rows[0]) for r in rows), "Inconsistent table columns"
    return rows


def add_sheet(name, rows, widths, tablename):
    ws = wb.create_sheet(name)
    n = len(rows[0])
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=n)
    ws.cell(1, 1, name).font = Font(name="Calibri", size=19, bold=True, color="FFFFFF")
    ws.cell(1, 1).fill = PatternFill("solid", fgColor=NAVY)
    ws.row_dimensions[1].height = 34
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=n)
    ws.cell(2, 1, "Критический анализ «Выручки» • Код и методика проверены; фактические суммы предприятия не сверялись")
    ws.cell(2, 1).font = Font(name="Calibri", size=11, italic=True, color="536577")
    ws.row_dimensions[2].height = 26
    ws.cell(3, 1, "К оглавлению").hyperlink = "#'Об отчёте'!A1"
    ws.cell(3, 1).style = "Hyperlink"
    for ri, row in enumerate(rows, 5):
        for ci, value in enumerate(row, 1):
            cell = ws.cell(ri, ci, value)
            cell.font = Font(name="Calibri", size=11, color="203449", bold=ci <= 2)
            cell.alignment = Alignment(vertical="top", wrap_text=True)
            if ri == 5:
                cell.fill = PatternFill("solid", fgColor=NAVY)
                cell.font = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
            elif ri % 2 == 0:
                cell.fill = PatternFill("solid", fgColor="F0F5FA")
            if value == "Критический":
                cell.fill = PatternFill("solid", fgColor="FCE4E4")
                cell.font = Font(name="Calibri", size=11, bold=True, color="A62626")
        lines = max(len(textwrap.wrap(v, width=max(6, int(w * .83)))) for v, w in zip(row, widths))
        ws.row_dimensions[ri].height = max(44 if ri == 5 else 70, min(390, lines * 15 + 16))
    for ci, width in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(ci)].width = width
    table = Table(displayName=tablename, ref=f"A5:{get_column_letter(n)}{ws.max_row}")
    table.tableStyleInfo = TableStyleInfo(name="TableStyleMedium2", showRowStripes=True)
    ws.add_table(table)
    ws.freeze_panes = "C6"
    ws.sheet_view.showGridLines = False
    ws.sheet_view.zoomScale = 75
    ws.print_title_rows = "1:5"
    ws.page_setup.orientation = "landscape"
    ws.page_setup.paperSize = ws.PAPERSIZE_A3
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.print_area = f"A1:{get_column_letter(n)}{ws.max_row}"
    ws.oddFooter.center.text = "Страница &P из &N"
    return len(rows) - 1


